@njit(parallel=True, fastmath=True, cache=True)
def accumulate(f, flags, acc):
    """Add rho, ux, uy, uz of every non-solid cell into acc[4, nx, ny, nz]."""
    nx, ny, nz = flags.shape
    for x in prange(nx):
        for y in range(ny):
            for z in range(nz):
                if flags[x, y, z] == 1:
                    continue
                f0 = f[0, x, y, z]
                f1 = f[1, x, y, z]
                f2 = f[2, x, y, z]
                f3 = f[3, x, y, z]
                f4 = f[4, x, y, z]
                f5 = f[5, x, y, z]
                f6 = f[6, x, y, z]
                f7 = f[7, x, y, z]
                f8 = f[8, x, y, z]
                f9 = f[9, x, y, z]
                f10 = f[10, x, y, z]
                f11 = f[11, x, y, z]
                f12 = f[12, x, y, z]
                f13 = f[13, x, y, z]
                f14 = f[14, x, y, z]
                f15 = f[15, x, y, z]
                f16 = f[16, x, y, z]
                f17 = f[17, x, y, z]
                f18 = f[18, x, y, z]
                rho = f0 + f1 + f2 + f3 + f4 + f5 + f6 + f7 + f8 + f9 + f10 + f11 + f12 + f13 + f14 + f15 + f16 + f17 + f18
                jx = f1 - f2 + f7 - f8 + f9 - f10 + f11 - f12 + f13 - f14
                jy = f3 - f4 + f7 - f8 - f9 + f10 + f15 - f16 + f17 - f18
                jz = f5 - f6 + f11 - f12 - f13 + f14 + f15 - f16 - f17 + f18
                irho = 1.0 / rho
                acc[0, x, y, z] += rho
                acc[1, x, y, z] += jx * irho
                acc[2, x, y, z] += jy * irho
                acc[3, x, y, z] += jz * irho
